using System;
using Kamilunavo.RepairEmpire.Core;
using Kamilunavo.RepairEmpire.Monetization;
namespace Kamilunavo.RepairEmpire.Validation {
 public static class RepairCommerceChecks {
 public static int Run(){int n=0;Action<bool,string> check=(ok,name)=>{n++;if(!ok)throw new Exception("REPAIR_COMMERCE_FAIL "+name);};var p=new RepairProfile();
 check(CommerceRules.FulfillPending(p,CommerceRules.Starter,"tx1",x=>{}),"first starter callback");check(p.Cash==1630&&p.Styles[4],"starter500 cash and permanent paint");check(CommerceRules.FulfillPending(p,CommerceRules.Starter,"tx1",x=>{})&&p.Cash==1630,"same transaction confirms without mint");check(CommerceRules.FulfillPending(p,CommerceRules.Starter,"tx2",x=>{})&&p.Cash==1630,"new starter order never repeats credit");check(!CommerceRules.FulfillPending(p,"unknown","tx3",x=>{}),"unknown product rejected");int wallet=p.Cash;bool failed=false;try{CommerceRules.FulfillPending(p,CommerceRules.Collection,"collection-fail",x=>{throw new Exception("disk");});}catch{failed=true;}check(failed&&p.Cash==wallet&&!p.Styles[5],"pending purchase save failure rollback");
 var restored=new RepairProfile();check(CommerceRules.RestoreEntitlement(restored,CommerceRules.Starter)&&restored.Cash==1130&&restored.Styles[4],"restore paint never pays currency");CommerceRules.FulfillPending(restored,CommerceRules.Starter,"afterrestore",x=>{});check(restored.Cash==1130,"restored starter cannot mint later");CommerceRules.RestoreEntitlement(restored,CommerceRules.Collection);restored.Style=7;CommerceRules.ReconcileEntitlements(restored,new string[0]);check(!restored.Styles[4]&&!restored.Styles[7]&&restored.Style==0,"revoked paints fall back safely");
 var now=new DateTime(2026,10,8,12,0,0,DateTimeKind.Utc);var ad=new RepairProfile();check(RewardRules.Fulfill(ad,"ad1",now,x=>{})&&ad.Cash==1180,"real completion rule pays50");check(!RewardRules.Fulfill(ad,"ad1",now.AddMinutes(2),x=>{}),"SDK replay rejected");check(!RewardRules.Fulfill(ad,"ad2",now.AddSeconds(59),x=>{}),"60second cooldown");for(int i=1;i<5;i++)check(RewardRules.Fulfill(ad,"ad"+(i+1),now.AddMinutes(i),x=>{}),"five valid completed sessions");check(ad.Cash==1380&&!RewardRules.CanClaim(ad,now.AddMinutes(10)),"five daily cap");check(!RewardRules.CanClaim(ad,now.AddDays(-1)),"reward reversed UTC cannot mint");check(RewardRules.Fulfill(ad,"nextday",now.AddDays(1),x=>{}),"next UTC day resets cap");
 var rejected=new RepairProfile();failed=false;try{RewardRules.Fulfill(rejected,"failed",now,x=>{throw new Exception();});}catch{failed=true;}check(failed&&rejected.Cash==1130&&RewardRules.Remaining(rejected,now)==5,"reward save rollback");var future=new RepairProfile{Schema=99};check(!CommerceRules.FulfillPending(future,CommerceRules.Starter,"future",x=>{})&&!RewardRules.CanClaim(future,now)&&future.Cash==1130,"unsupported schema blocks monetization");
 var clone=p.Clone();clone.Commerce.FulfilledTransactions.Add("notoriginal");clone.Rewards.Sessions.Add("notoriginal");check(!p.Commerce.FulfilledTransactions.Contains("notoriginal")&&!p.Rewards.Sessions.Contains("notoriginal"),"transaction snapshots own mutable lists");var gate=new StoreReconnectGate();check(gate.TryBegin(0)&&!gate.TryBegin(1),"single outstanding connection");gate.Failed(0);check(!gate.CanBegin(6),"failure callback cannot overlap pending connect");gate.EndAttempt();check(!gate.CanBegin(4)&&gate.TryBegin(5),"same session retry after bounded cooldown");Console.WriteLine("REPAIR_COMMERCE_PASS "+n);return n;}
#if REPAIR_COMMERCE_EXE
 public static void Main(){Run();}
#endif
 }
}
